def pw(i,l,auto,meter=False): return f'<div class="field"><label for="{i}">{l}</label><div class="pw-wrap"><input id="{i}" name="{i}" type="password" required minlength="8" autocomplete="{auto}"><button class="pw-toggle" type="button" data-for="{i}" aria-label="Show or hide {l.lower()}">Show</button></div>'+('<div class="meter" id="meter" aria-hidden="true"><i></i></div><p class="hint" id="meter-label" aria-live="polite"></p>' if meter else '')+'</div>'
