def grp(name,opts): return '<div class="checks">'+''.join(f'<label><input type="checkbox" data-group="{name}" name="{name}" value="{o}"> {o}</label>' for o in opts)+'</div>'
w('become-friend.html','Become a Friend','Apply to become a companion. Set your rate and hours. Verification required before listing.',f'''{head("Become a friend","Earn by sharing your time and good company. You decide your hours, rate and activities.")}
<section class="section tight"><div class="container layout-apply"><div class="prose"><h2 style="margin-top:0">Why join</h2><ul><li><strong>Flexible:</strong> set your own days and hours.</li><li><strong>Fair:</strong> you set your hourly rate; the platform fee is shown upfront (10%).</li><li><strong>Safe:</strong> block, report and boundary tools.</li></ul><h2>How earning works</h2><p>Guests book and pay through the platform. After a completed booking, your earnings minus the fee are paid out. Payouts need a payment provider and are not live yet.</p>
<div class="alert-box">Applications are subject to identity and safety verification before a profile is publicly listed. Companionship only: no sexual services.</div></div>
<div><div id="apply-status"></div><form class="card pad" data-form="apply" novalidate><h2 style="font-size:1.5rem">Create your profile</h2>
<div class="row2"><div class="field"><label for="n">Full name</label><input id="n" name="name" required minlength="2" autocomplete="name"></div><div class="field"><label for="age">Age (18+)</label><input id="age" name="age" type="number" min="18" max="99" required></div></div>
<div class="row2"><div class="field"><label for="city">City</label><input id="city" name="city" required autocomplete="address-level2"></div><div class="field"><label for="rate">Hourly rate (₹)</label><input id="rate" name="rate" type="number" min="200" max="5000" required></div></div>
<div class="row2"><div class="field"><label for="em">Email</label><input id="em" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="ph">Phone</label><input id="ph" name="phone" type="tel" required autocomplete="tel"></div></div>
<div class="field"><label for="int">Interests (comma separated)</label><input id="int" name="interests" required></div><div class="field"><label for="lang">Languages</label><input id="lang" name="languages" required></div>
<div class="field"><label for="bio">Short bio</label><textarea id="bio" name="bio" required minlength="40" maxlength="500"></textarea><p class="hint">40–500 characters. Keep it friendly and platonic.</p></div>
<div class="field"><span class="label">Available days</span>{grp("days",["Weekdays","Weekends"])}</div>
<div class="field"><span class="label">Time slots</span>{grp("slots",["Mornings","Afternoons","Evenings"])}</div>
<div class="field"><label for="photo">Profile photo (JPG, PNG or WebP, max 3 MB)</label><input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"><div id="photo-preview"></div><p class="hint">Your photo is checked during review. Leave it out to use an illustrated avatar.</p></div>
<div class="check"><input type="checkbox" id="t" name="terms" required data-msg="You must accept to apply."><label for="t">I confirm I am 18+ and accept the <a href="terms.html">Terms</a> and <a href="community-guidelines.html">Community Guidelines</a>.</label></div>
<button class="btn btn-primary" type="submit">Submit application</button></form></div></div></section>''')
w('dashboard.html','Dashboard','Your bookings, favourites, notifications and settings.','<section class="section tight"><div class="container"><h1 style="font-size:2rem">Dashboard</h1><div id="dash-root"></div></div></section>',js=['dashboard'])
w('contact.html','Contact','Get in touch with Rent A Friend.',f'''{head("Contact us","Questions, feedback or safety concerns. [Support email and address to be added.]")}<section class="section tight"><div class="container"><form class="card pad form-card" data-form="contact" novalidate><div class="field"><label for="n">Name</label><input id="n" name="name" required></div><div class="field"><label for="e">Email</label><input id="e" name="email" type="email" required></div><div class="field"><label for="m">Message</label><textarea id="m" name="message" required minlength="10"></textarea></div><button class="btn btn-primary" type="submit">Send message</button></form></div></section>''')
